CHAPTERS = {"basics_hw", "basics_cuda", "basics_triton", "basics_workflow", "landscape"}

for name, body in S.items():
    p = C / f"{name}.md"
    s = p.read_text()
    if "## 源码与资料" in s:
        continue
    sec = f"## 源码与资料\n\n{body}\n\n"
    if name in CHAPTERS:
        if "## 来源" in s:                       # landscape: put links before its source list
            s = s.replace("## 来源", sec + "## 来源", 1)
        else:
            s = s.rstrip("\n") + "\n\n" + sec
    else:
        i = s.index("## 背景")
        j = s.index("\n## ", i + 1) + 1          # start of the section after 背景
        s = s[:j] + sec + s[j:]
    p.write_text(s)
    print("added", name)
